// ESLint flat config — TIN Command Center (task W1-07: the repository had no linter).
//
// Rules derive from recognised presets, matching the estate's other repositories:
//   - @eslint/js recommended
//   - typescript-eslint recommended
// Nothing below bulk-disables a preset; each adjustment is scoped and commented.
import js from "@eslint/js";
import globals from "globals";
import tseslint from "typescript-eslint";

export default tseslint.config(
  {
    ignores: [
      "**/node_modules/**",
      "**/.next/**",
      "**/coverage/**",
      // Generated by scripts/export-catalog.mjs; never committed (see docs/authority-model.md).
      "**/catalog/**",
      "next-env.d.ts",
    ],
  },
  js.configs.recommended,
  ...tseslint.configs.recommended,
  {
    // Node built-ins for plain-JS tooling: scripts/*.mjs and the config files.
    files: ["**/*.mjs", "**/*.js", "**/*.cjs"],
    languageOptions: {
      globals: { ...globals.node },
    },
  },
  {
    files: ["**/*.ts", "**/*.tsx"],
    languageOptions: {
      globals: { ...globals.node, ...globals.browser },
    },
    rules: {
      // TypeScript already enforces this with real type information.
      "no-undef": "off",
      // Raw database rows are `Record<string, any>` at the boundary (src/*/db.ts),
      // and the test helpers default their row type to `any` to mirror them. This
      // is the estate convention in sibling repositories (shell-base-admin,
      // shell-base-cxp); adjusted here so the preset is not bulk-disabled.
      "@typescript-eslint/no-explicit-any": "off",
      // Standard convention: underscore-prefixed bindings are intentionally unused.
      "@typescript-eslint/no-unused-vars": [
        "error",
        {
          argsIgnorePattern: "^_",
          varsIgnorePattern: "^_",
          caughtErrorsIgnorePattern: "^_",
          destructuredArrayIgnorePattern: "^_",
        },
      ],
    },
  },
);
